import json, collections, statistics, re, math
base='/user/user1/harbor-runs/40eca6ba7f68/workspace/outputs/frozen_eval/'
R={s:[json.loads(l) for l in open(base+str(s)+'.jsonl')] for s in (0,150)}
for s,rows in R.items():
 print('\nSTEP',s)
 for key in ['data_source','context_bucket']:
  for val in sorted(set(x[key] for x in rows)):
   z=[x for x in rows if x[key]==val]; print(key,val,'n',len(z),'correct',sum(x['acc'] for x in z),'acc',sum(x['acc'] for x in z)/len(z),'unique_outputs',len(set(x['output'] for x in z)))
 groups=collections.defaultdict(list)
 for x in rows: groups[x['problem_id']].append(x)
 for k in (1,2,4,8,16,32):
  p=sum(any(y['acc'] for y in v[:k]) for v in groups.values())/len(groups)
  # exact unbiased pass@k from 32 samples
  ps=[]
  for v in groups.values():
   c=sum(y['acc'] for y in v); n=len(v)
   ps.append(1 if c==n else 1-math.comb(n-int(c),k)/math.comb(n,k) if n-int(c)>=k else 1)
  print('pass@',k,'ordered',p,'unbiased_mean',statistics.mean(ps))
 print('problems_any_correct',sum(any(y['acc'] for y in v) for v in groups.values()),'all_correct',sum(all(y['acc'] for y in v) for v in groups.values()))
# paired per problem changes
G={s:collections.defaultdict(list) for s in R}
for s,rows in R.items():
 for x in rows:G[s][x['problem_id']].append(x)
print('\nPAIRED PROBLEM TRANSITIONS')
trans=collections.Counter()
for pid in sorted(G[0]):
 a=sum(x['acc'] for x in G[0][pid]); b=sum(x['acc'] for x in G[150][pid]); trans[('any0' if a else 'none0','any150' if b else 'none150')]+=1
 if a or b: print(pid,'correct0',a,'correct150',b,'unique0',len(set(x['output'] for x in G[0][pid])),'unique150',len(set(x['output'] for x in G[150][pid])))
print(trans)
PY

