arguments.command:
python -I - <<'PY'
import json,collections,re,statistics
from pathlib import Path
root=Path('/user/user1/harbor-runs/40eca6ba7f68/workspace/outputs')
for rel in ['frozen_eval/0.jsonl','frozen_eval/150.jsonl','rollouts/150.jsonl']:
 rows=[json.loads(s) for s in (root/rel).read_text().splitlines()]
 bysrc=collections.defaultdict(list)
 for r in rows: bysrc[r['data_source']].append(r)
 print('\n'+rel)
 for src,rs in bysrc.items():
  print(src,'n',len(rs),'accuracy',sum(r['acc'] for r in rs)/len(rs),'nonempty',sum(bool(r['output'].strip()) for r in rs)/len(rs))
  if 'frozen' in rel:
   byid=collections.defaultdict(list)
   for r in rs:byid[r['problem_id']].append(r['acc'])
   print('problems with >=1 correct',sum(any(v) for v in byid.values()),'of',len(byid))
 print('Most common exact outputs:')
 for text,n in collections.Counter(r['output'] for r in rows).most_common(5):
  print(n,repr(text[:180]))
PY

